//! Wolfram exact SpMV replay: A x, A^T x and A^H x.
//!
//! The fixture (`sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json`,
//! generated by `sonium-qa/wolfram/exact_linear_algebra.wls`) carries exact
//! matrices with independent action references, per
//! audit-sonium-solvers-sparse-20260921. A duplicate/unsorted triplet build
//! must reproduce the canonical build bit-for-bit.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_solvers_sparse::CsrMatrix;

const FIXTURE: &str =
    include_str!("../../../../../crates/sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json");

#[derive(Debug, Deserialize)]
struct ComplexScalar {
    re: String,
    im: String,
}

#[derive(Debug, Deserialize)]
struct RealAction {
    a: Vec<Vec<String>>,
    x_exact: Vec<String>,
    b: Vec<String>,
    atx: Vec<String>,
    y: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct ComplexAction {
    a: Vec<Vec<ComplexScalar>>,
    v: Vec<ComplexScalar>,
    hv: Vec<ComplexScalar>,
    hermitian_v: Vec<ComplexScalar>,
    transpose_v: Vec<ComplexScalar>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    nonsym_3x3: RealAction,
    rect_4x3: RealAction,
    hermitian_3x3: ComplexAction,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_complex(value: &ComplexScalar) -> Complex64 {
    Complex64::new(parse(&value.re), parse(&value.im))
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("valid exact linear-algebra fixture");
    assert_eq!(fixture.schema, "sonium-qa.exact-linear-algebra.v1");
    fixture
}

fn real_matrix(rows: &[Vec<String>]) -> CsrMatrix<f64> {
    let triplets = rows
        .iter()
        .enumerate()
        .flat_map(|(i, row)| {
            row.iter()
                .enumerate()
                .map(move |(j, value)| (i, j, parse(value)))
        })
        .collect();
    CsrMatrix::from_triplets(rows.len(), rows[0].len(), triplets)
}

fn assert_close(actual: &[f64], expected: &[String], label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
    for (index, (&got, want)) in actual.iter().zip(expected).enumerate() {
        let want = parse(want);
        assert!(
            (got - want).abs() <= 1e-12 * want.abs().max(1.0),
            "{label}[{index}]: {got:e} != {want:e}"
        );
    }
}

fn assert_complex_close(actual: &[Complex64], expected: &[ComplexScalar], label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
    for (index, (got, want)) in actual.iter().zip(expected).enumerate() {
        let want = parse_complex(want);
        assert!(
            (got - want).norm() <= 1e-12 * want.norm().max(1.0),
            "{label}[{index}]: {got:?} != {want:?}"
        );
    }
}

#[test]
fn nonsymmetric_actions_match_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.nonsym_3x3;
    let matrix = real_matrix(&case.a);
    let x: Vec<f64> = case.x_exact.iter().map(|value| parse(value)).collect();
    let y: Vec<f64> = case.y.iter().map(|value| parse(value)).collect();
    assert_close(&matrix.matvec(&x), &case.b, "nonsym A x");
    assert_close(&matrix.matvec_transpose(&y), &case.atx, "nonsym A^T y");
}

#[test]
fn rectangular_actions_match_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.rect_4x3;
    let matrix = real_matrix(&case.a);
    assert_eq!(matrix.num_rows, 4);
    let x: Vec<f64> = case.x_exact.iter().map(|value| parse(value)).collect();
    let y: Vec<f64> = case.y.iter().map(|value| parse(value)).collect();
    assert_close(&matrix.matvec(&x), &case.b, "rect A x");
    assert_close(&matrix.matvec_transpose(&y), &case.atx, "rect A^T y");
}

#[test]
fn hermitian_actions_match_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.hermitian_3x3;
    let triplets = case
        .a
        .iter()
        .enumerate()
        .flat_map(|(i, row)| {
            row.iter()
                .enumerate()
                .map(move |(j, value)| (i, j, parse_complex(value)))
        })
        .collect();
    let matrix = CsrMatrix::from_triplets(3, 3, triplets);
    let v: Vec<Complex64> = case.v.iter().map(parse_complex).collect();
    assert_complex_close(&matrix.matvec(&v), &case.hv, "hermitian A v");
    assert_complex_close(
        &matrix.matvec_hermitian(&v),
        &case.hermitian_v,
        "hermitian A^H v",
    );
    assert_complex_close(
        &matrix.matvec_transpose(&v),
        &case.transpose_v,
        "hermitian A^T v",
    );
}

#[test]
fn duplicate_unsorted_triplets_reproduce_canonical_actions() {
    // Public-mutation robustness: the same matrix assembled from shuffled,
    // duplicated triplets must give identical actions (duplicates summed).
    let fixture = parse_fixture();
    let case = &fixture.nonsym_3x3;
    let mut triplets = case
        .a
        .iter()
        .enumerate()
        .flat_map(|(i, row)| {
            row.iter()
                .enumerate()
                .map(move |(j, value)| (i, j, parse(value)))
        })
        .collect::<Vec<_>>();
    triplets.reverse();
    triplets.extend_from_slice(&[(0, 0, 0.0), (2, 2, 0.0)]);
    let shuffled = CsrMatrix::from_triplets(3, 3, triplets);
    let canonical = real_matrix(&case.a);
    let x: Vec<f64> = case.x_exact.iter().map(|value| parse(value)).collect();
    assert_close(&shuffled.matvec(&x), &case.b, "shuffled A x");
    assert_eq!(shuffled.matvec(&x), canonical.matvec(&x));
}
